static int nib(char c)
{
    return c <= '9' ? c - '0' : (c | 32) - 'a' + 10;
}

static void unhex_sb(const char *s, sb_t *out)
{
    for (; s[0] && s[1]; s += 2) {
        char b = (char)(nib(s[0]) << 4 | nib(s[1]));
        sb_addn(out, &b, 1);
    }
}

static int same_hex(const unsigned char *got, size_t n, const char *want)
{
    sb_t w = {0};
    int ok;

    unhex_sb(want, &w);
    ok = w.len == n && ct_equal(got, w.data, n);
    sb_free(&w);
    return ok;
}

static void tree_math(void)
{
    int ok = 1;

    for (int i = 0; i < (int)(sizeof k_math / sizeof *k_math); i++) {
        unsigned n = k_math[i].n_leaves, root = mls_root(n);
        ok &= root == k_math[i].root;
        for (unsigned x = 0; x < mls_nodes(n); x++) {
            const unsigned *v = k_math[i].nodes[x];
            if (x % 2)
                ok &= mls_left(x) == v[0] && mls_right(x) == v[1];
            if (x != root)
                ok &= mls_parent(x) == v[2] && mls_sibling(x) == v[3];
        }
    }
    check(ok, "tree math");
}

static void tree_validation(void)
{
    for (int i = 0; i < (int)(sizeof k_trees / sizeof *k_trees); i++) {
        sb_t raw = {0}, gid = {0}, again = {0};
        mls_tree_t t;
        unsigned res[128];
        const int *want = k_trees[i].res;
        int ok;
        for (int k = 0; k_trees[i].tree[k]; k++)
            unhex_sb(k_trees[i].tree[k], &raw);
        unhex_sb(k_trees[i].group_id, &gid);
        ok = mls_tree_parse(&t, (const unsigned char *)raw.data, raw.len);
        check(ok && mls_nodes(t.nleaves) == k_trees[i].nodes, "tree parses");
        if (!ok)
            continue;
        mls_tree_serialize(&t, &again);
        check(again.len == raw.len && ct_equal(again.data, raw.data, raw.len), "tree round trip");
        int hashes = 1, resolutions = 1;
        for (unsigned x = 0; x < k_trees[i].nodes; x++) {
            unsigned char h[32];
            int n = mls_resolution(&t, x, res);
            mls_tree_hash(&t, x, h);
            hashes &= same_hex(h, 32, k_trees[i].hashes[x]);
            resolutions &= n == *want;
            for (int k = 0; resolutions && k < n; k++)
                resolutions &= (int)res[k] == want[1 + k];
            want += 1 + *want;
        }
        check(hashes, "tree hashes");
        check(resolutions, "resolutions");
        check(mls_tree_verify_leaves(&t, gid.data, gid.len), "leaf signatures");
        check(mls_tree_verify_parent_hashes(&t), "parent hashes");
        /* A flipped bit in a parent hash breaks the chain. */
        for (unsigned x = 1; x < mls_nodes(t.nleaves); x += 2)
            if (t.nodes[x].present && t.nodes[x].parent_hash.len) {
                t.nodes[x].parent_hash.data[3] ^= 1;
                check(!mls_tree_verify_parent_hashes(&t), "tampered parent hash");
                t.nodes[x].parent_hash.data[3] ^= 1;
                break;
            }
        mls_tree_free(&t);
        sb_free(&raw);
        sb_free(&gid);
        sb_free(&again);
    }
}

static void extend_truncate(void)
{
    mls_tree_t t = {0};

    mls_tree_extend(&t, 3);
    check(t.nleaves == 4 && mls_nodes(t.nleaves) == 7, "extend");
    t.nodes[0].present = 1;
    t.nodes[2].present = 1;
    mls_tree_truncate(&t);
    check(t.nleaves == 2, "truncate");
    mls_tree_free(&t);
}

void entry(void)
{
    tree_math();
    tree_validation();
    extend_truncate();
    finish();
}
